SELECT day, COUNT(*) AS flights
FROM flights WHERE origin_cc = 'QA' OR destination_cc = 'QA'
GROUP BY 1 ORDER BY 1;

SELECT day, COUNT(*) AS flights
FROM flights WHERE pair = 'EBBR-EKCH'
GROUP BY 1 ORDER BY 1;

SELECT day, COUNT(*) AS flights
FROM flights WHERE pair = 'EKCH-LEMD'
GROUP BY 1 ORDER BY 1;

SELECT day, COUNT(*) AS flights
FROM flights WHERE origin_cc = 'HR' OR destination_cc = 'HR'
GROUP BY 1 ORDER BY 1;

SELECT day, COUNT(*) AS flights
FROM flights WHERE pair = 'EGLL-ESSA'
GROUP BY 1 ORDER BY 1;

SELECT day, COUNT(*) AS flights
FROM flights WHERE origin_cc = 'US' OR destination_cc = 'US'
GROUP BY 1 ORDER BY 1;

SELECT origin, destination, COUNT(*) AS flights
FROM flights WHERE pair = 'EKCH-EKYT'
GROUP BY 1, 2;

SELECT pair, origin_name, destination_name, COUNT(*) AS flights
FROM flights WHERE pair IN ('LEBL-ZSPD', 'EGKK-ZGGG', 'LFPG-ZGGG')
GROUP BY 1, 2, 3 ORDER BY 4 DESC;

SELECT strftime(seen_at, '%Y-%m-%d') AS day,
       COUNT(*) AS flights
FROM flights GROUP BY 1 ORDER BY 2 DESC;

SELECT origin_city, destination_city, COUNT(*) AS flights
FROM flights WHERE origin_cc = 'CN' OR destination_cc = 'CN'
GROUP BY 1, 2 ORDER BY 3 DESC;

SELECT origin_city, destination_city, COUNT(*) AS flights
FROM flights WHERE origin_cc = 'US' OR destination_cc = 'US'
GROUP BY 1, 2 ORDER BY 3 DESC;
